def display_message():
    print("saya mempelajari teknik dasar pembuatan blok kode mandiri menggunakan kata kunci def disertai dokumentasi docstring. Selain itu, dipelajari pula cara pengiriman argumen fungsi, baik secara berurutan (positional arguments) maupun secara eksplisit melalui nama parameternya (keyword arguments), serta penggunaan nilai default agar parameter menjadi opsional. Materi ini juga membahas mekanisme pengembalian nilai menggunakan kata kunci return untuk mengolah data seperti string atau dictionary, penggabungan fungsi bersama perulangan while dan input interaktif pengguna, serta teknik manipulasi tipe data list di dalam fungsi menggunakan metode seperti .pop() dan .append().")

# Memanggil fungsi
display_message()